import { Monster, MoveInstance, LogEntry, ItemType, ExtrasInventory, GymStatus, JourneyState } from './types';
import { getToken } from './auth';

// Where the backend lives. When the API runs on its own host (Render), set NEXT_PUBLIC_API_URL in the
// Vercel project's Environment Variables to e.g. https://poshow.onrender.com (no trailing slash) and
// REDEPLOY — NEXT_PUBLIC_ values are baked in at build time. Empty = same-origin /api (everything on Vercel).
export const API_BASE = (process.env.NEXT_PUBLIC_API_URL || '').replace(/\/+$/, '');

/** trainer avatar sprite (pixel art generated by the API) */
export function avatarUrl(id: string | null | undefined, scale = 6): string {
  return `${API_BASE}/api/avatars/${id || 'ember'}.png?scale=${scale}`;
}

export class ApiError extends Error {
  constructor(message: string, public status?: number) {
    super(message);
    this.name = 'ApiError';
  }
}

// free hosting sleeps when idle and the first request after that can take ~50s — so the default is
// generous, and the health check below is even more patient
const DEFAULT_TIMEOUT_MS = 30000;

async function request<T>(path: string, init?: RequestInit, timeoutMs = DEFAULT_TIMEOUT_MS): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  const token = getToken();
  let res: Response;
  try {
    res = await fetch(`${API_BASE}${path}`, {
      ...init,
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...(init?.headers ?? {}),
      },
    });
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') {
      throw new ApiError('Request timed out — the server took too long to respond.');
    }
    throw new ApiError(err instanceof Error ? err.message : 'Network request failed.');
  } finally {
    clearTimeout(timeout);
  }

  if (!res.ok) {
    let detail = res.statusText;
    try {
      const body = await res.json();
      detail = body.detail ?? detail;
    } catch {
      // response wasn't JSON — keep statusText
    }
    throw new ApiError(detail, res.status);
  }
  return res.json() as Promise<T>;
}

// server response shapes (mirrors api/index.py) ⚙
export interface ServerMove {
  id: string;
  name: string;
  type: string;
  power: number;
  accuracy: number;
  pp: number;
  max_pp: number;
}

export interface ServerPokemon {
  id: string;
  species_name: string;
  nickname: string;
  level: number;
  current_hp: number;
  max_hp: number;
  experience: number;
  xp_to_next: number;
  types: string[];
  moves: ServerMove[];
  is_shiny: boolean;
  is_fainted: boolean;
  pokedex_id: number | null;
  ability?: string | null;
  ability_desc?: string | null;
  is_boss?: boolean;
  gym_floor?: number;
}

export interface StartBattleResponse {
  battle_id: string;
  player_pokemon: ServerPokemon;
  wild_pokemon: ServerPokemon;
  log: string[];
}

export interface ScoutResponse {
  candidates: ServerPokemon[];
}

export interface BattleMoveResponse {
  log: string[];
  is_finished: boolean;
  winner: 'player' | 'wild' | null;
  player_pokemon: ServerPokemon;
  wild_pokemon: ServerPokemon;
  xp_gained?: number;
  coins_gained?: number;
  /** present on a win */
  team?: ServerPokemon[];
  inventory?: Record<string, number>;
  pokeballs?: Record<string, number>;
  exp_all?: { used: boolean; per_pokemon: number; pokemon_count: number; level_ups: string[] };
  boss?: { defeated: boolean; flawless: boolean; items: [string, number][] };
  /** story trainer: either {advanced...} (next Pokémon sent out), a win summary, or a loss summary */
  story?: {
    advanced?: boolean;
    name?: string;
    idx?: number;
    size?: number;
    won?: boolean;
    coins?: number;
    badge?: string | null;
    win?: string;
    complete?: boolean;
    unlocked_region?: string | null;
    items?: Record<string, number>;
    blackout?: boolean;
    remaining?: number;
    location?: string;
  };
  gym?: {
    // win
    floor_cleared?: number;
    bp?: number;
    coins?: number;
    badge?: string | null;
    next_floor?: number;
    best?: number;
    total_bp?: number;
    // loss
    run_over: boolean;
    remaining?: number;
    floors_cleared?: number;
  };
}

